#!/bin/bash
# Arknights: Endfield — direct launcher.
#
# Generated by the FineWine Patcher / install scripts from LauncherTemplate.sh.
# Double-clicking this app starts the target below through the patched CrossOver using the
# *direct* wine path (wine --bottle … --cx-app …). That path stays up where the CrossOver
# GUI's Start button does not (the GUI path is what crashes the launcher's Chromium renderer —
# see docs/project-information/15-launcher-qtwebengine-crash.md).
#
# Default target: the Gryphline launcher (Launcher.exe) — use it to install/update/play.
# Point it at the game with: scripts/make-launcher-app.sh --target "C:/…/Endfield.exe" --gfxargs -force-d3d11
#
# Placeholders substituted at generation time: @CX_APP@ @BUNDLE_ID@ @BOTTLE@ @TARGET@ @GFXARGS@

set -uo pipefail

# Path this app was generated for (a hint; the .app may since have been renamed).
CX_APP_HINT="@CX_APP@"
# The patched CrossOver's bundle identifier — lets us find it even if the .app is renamed.
BUNDLE_ID="@BUNDLE_ID@"
BOTTLE="@BOTTLE@"
TARGET="@TARGET@"
GFXARGS="@GFXARGS@"

bundle_id_of() {
  plutil -extract CFBundleIdentifier raw "$1/Contents/Info.plist" 2>/dev/null \
    || defaults read "$1/Contents/Info" CFBundleIdentifier 2>/dev/null
}

# A real CrossOver install ships this payload. Reject anything else (a matching Info.plist is not enough).
is_cx_app() {
  [ -d "$1/Contents/SharedSupport/CrossOver/bin" ] \
    && [ -x "$1/Contents/SharedSupport/CrossOver/bin/wine" ]
}

# Only accept installs under the trusted, non-user-writable root dirs. This stops a same-bundle-id
# bundle sitting somewhere writable (Downloads, /tmp, a mounted image, iCloud, …) from being run.
is_trusted_install() {
  case "$1" in
    /Applications/*|"$HOME"/Applications/*) return 0 ;;
    *) return 1 ;;
  esac
}

# A candidate from Spotlight/scan must be a trusted install, carry the right bundle id, and be a
# real CrossOver tree.
is_cx_candidate() {
  is_trusted_install "$1" || return 1
  [ "$(bundle_id_of "$1")" = "$BUNDLE_ID" ] || return 1
  is_cx_app "$1"
}

# Find the patched CrossOver app. The filename is not reliable (it can be renamed), so match on the
# bundle identifier: FINEWINE_CX_APP override -> generated-path hint -> Spotlight -> scan the trusted
# roots. Spotlight results are filtered to trusted roots + a verified payload (never execute a bundle
# from a writable location). This is also what lets a prebuilt copy work on any machine.
resolve_cx_app() {
  # Break the stdin loop out of any inherited stdin (a double-clicked .app has none) and avoid globs.
  local cand app oldifs
  if [ -n "${FINEWINE_CX_APP:-}" ] && is_cx_app "${FINEWINE_CX_APP}"; then
    printf '%s' "$FINEWINE_CX_APP"; return
  fi
  if [ -n "$CX_APP_HINT" ] && is_cx_app "$CX_APP_HINT"; then
    printf '%s' "$CX_APP_HINT"; return
  fi
  if command -v mdfind >/dev/null 2>&1; then
    while IFS= read -r cand; do
      [ -n "$cand" ] || continue
      if is_cx_candidate "$cand"; then printf '%s' "$cand"; return; fi
    done < <(mdfind "kMDItemCFBundleIdentifier == '$BUNDLE_ID'" 2>/dev/null)
  fi
  for app in /Applications/*.app "$HOME"/Applications/*.app; do
    if is_cx_candidate "$app"; then printf '%s' "$app"; return; fi
  done
}

CX_APP="$(resolve_cx_app)"

CXR="$CX_APP/Contents/SharedSupport/CrossOver"
CXBIN="$CXR/bin"
BP="$HOME/Library/Application Support/CrossOver/Bottles/$BOTTLE"

alert() { osascript -e "display alert \"Arknights: Endfield\" message \"$1\"" >/dev/null 2>&1 || echo "$1" >&2; }

[ -n "$CX_APP" ] && [ -d "$CX_APP" ] || { alert "Patched CrossOver not found (install it from the FineWine Patcher, or set FINEWINE_CX_APP)."; exit 1; }
[ -x "$CXBIN/wine" ] || { alert "wine not found under $CX_APP"; exit 1; }
[ -d "$BP" ] || { alert "Bottle '$BOTTLE' not found. Create it first (scripts/create-bottle.sh)."; exit 1; }

# Clean stale Wine/ACE state so the anti-cheat starts fresh.
WINEPREFIX="$BP" CX_ROOT="$CXR" "$CXBIN/wineserver" -k >/dev/null 2>&1 || true
sleep 1

OUT="$HOME/endfield-debug/launcher-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$OUT"

# --wait-children keeps this app alive until the game exits. The game has its own login UI,
# so the Gryphline launcher is not needed (use it only to update the game).
"$CXBIN/wine" --bottle "$BOTTLE" --wait-children --cx-app "$TARGET" $GFXARGS > "$OUT/wine.log" 2>&1
